with temp as (select requester_id as id , count(requester_id) as cnt from RequestAccepted group by requester_id) , temp1 as (select accepter_id as id , count(accepter_id) as cnt from RequestAccepted group by id ) , temp2 as (select * from temp union all select * from temp1)
select id , sum(cnt) as num from temp2 group by id order by num desc limit 1